import { useEffect, useState } from "react";

export type Step = {
  name: string;
  command: string;
  exit_code: number;
  duration_s?: number;
  started?: number;
  ended?: number;
  output_tail?: string[];
  package_manager?: string;
};

export type Attempt = {
  source?: string;
  kind?: string;
  files?: string[];
  rationale?: string;
  confidence?: number;
  result?: string;
  status?: string;
  recovered_from_invalid_json?: boolean;
  files_content?: { path: string; content: string }[];
};

export type ModelCall = {
  started?: number;
  duration_s?: number;
  status?: string;
  model?: string;
  effort?: string;
  prompt_chars?: number;
  response_chars?: number;
  tokens_estimated?: { prompt_tokens: number; completion_tokens: number; total_tokens: number };
};

export type Side = {
  passed?: boolean;
  status?: string;
  detail?: string;
  package_manager?: string;
  rules_fired?: string[];
  attempts?: Attempt[];
  steps?: Step[];
  gaps?: string[];
};

export type RunResult = {
  run_id: string;
  repo: string;
  sha: string;
  path?: string;
  agent_version?: string;
  started?: number;
  ended?: number;
  agent?: Side;
  verifier?: Side;
  type?: string;
  type_why?: string;
  image?: string;
  cap_minutes?: number;
  model_calls?: ModelCall[];
  needs_approval?: boolean;
  last_failure?: { step: string; command: string; exit_code: number } | null;
  gaps?: string[];
  fixed?: boolean;
  result?: string;
  trace_id?: string;
};

export type StepBrief = { name: string; ok: boolean; duration_s: number | null };

export type AttemptBrief = {
  kind: string | null;
  files: string[];
  result: string | null;
  status: string | null;
  confidence: number | null;
  rationale: string | null;
};

/**
 * One row of /api/runs. The first block is always there (older records can have null `type` or
 * `fix_kind`). The second block was added later and the list may omit it: read steps, attempts and
 * the rest from /api/runs/{id} instead, and never assume these exist.
 */
export type RunSummary = {
  id: string;
  repo: string | null;
  sha: string | null;
  path: string;
  type: string | null;
  status: string;
  duration_s: number | null;
  model_calls: number;
  fix_kind: string | null;
  needs_approval: boolean;
  started: number | null;
  verified?: boolean;
  gaps?: string[];
  agent_steps?: StepBrief[];
  verifier_steps?: StepBrief[];
  attempts?: AttemptBrief[];
  rules_fired?: string[];
  model?: string | null;
  model_seconds?: number | null;
  error_line?: string | null;
  problems?: { key: string; evidence: string }[];
  patch_preview?: string | null;
  patch_added?: number;
};

export type RunDetail = { summary: RunSummary; result: RunResult; fix_patch: string | null };

type Async<T> = { data: T | null; error: string | null; loading: boolean };

function useFetch<T>(url: string | null): Async<T> {
  const [state, setState] = useState<Async<T>>({ data: null, error: null, loading: url !== null });
  useEffect(() => {
    if (url === null) {
      setState({ data: null, error: null, loading: false });
      return;
    }
    const ctl = new AbortController();
    setState({ data: null, error: null, loading: true });
    fetch(url, { signal: ctl.signal })
      .then(async (r) => {
        if (!r.ok) throw new Error(r.status === 404 ? "Not found" : `Request failed (${r.status})`);
        return (await r.json()) as T;
      })
      .then((data) => setState({ data, error: null, loading: false }))
      .catch((e: unknown) => {
        if ((e as Error).name !== "AbortError") setState({ data: null, error: (e as Error).message, loading: false });
      });
    return () => ctl.abort();
  }, [url]);
  return state;
}

export const useRuns = () => useFetch<RunSummary[]>("/api/runs");
/** One run's full record. Pass null to fetch nothing. */
export const useRun = (id: string | null) => useFetch<RunDetail>(id ? `/api/runs/${encodeURIComponent(id)}` : null);

export type InstallRepo = {
  repo: string;
  sha?: string;
  path?: string;
  state: "queued" | "checking" | "done" | "skipped" | string;
  reason?: string | null;
  run_id?: string | null;
  result?: "runs" | "runs_with_gaps" | "broken" | "unsupported" | null;
  needs_approval?: boolean;
  pr?: { url: string; number?: number } | null;
};

/** `$QUEUE_DIR/status/<id>.json` as the worker writes it, or `{installation_id, state: "received"}`. */
export type Installation = {
  installation_id: number;
  state: "received" | "checking" | "done" | "rejected" | string;
  account?: string;
  updated?: string;
  reason?: string | null;
  repos?: InstallRepo[];
};

const INSTALL_POLL_MS = 5000;

/** One installation's status, re-fetched every 5 s until the worker reports `done` or `rejected`. */
export function useInstallation(id: string): Async<Installation> {
  const [state, setState] = useState<Async<Installation>>({ data: null, error: null, loading: true });
  useEffect(() => {
    const ctl = new AbortController();
    let timer = 0;
    setState({ data: null, error: null, loading: true });
    const tick = async () => {
      try {
        const r = await fetch(`/api/installations/${encodeURIComponent(id)}`, { signal: ctl.signal });
        if (!r.ok) throw new Error(r.status === 404 ? "Not found" : `Request failed (${r.status})`);
        const data = (await r.json()) as Installation;
        setState({ data, error: null, loading: false });
        if (data.state === "done" || data.state === "rejected") return;
      } catch (e) {
        if ((e as Error).name === "AbortError") return;
        setState((s) => ({ data: s.data, error: (e as Error).message, loading: false }));
      }
      timer = window.setTimeout(tick, INSTALL_POLL_MS);
    };
    void tick();
    return () => {
      ctl.abort();
      window.clearTimeout(timer);
    };
  }, [id]);
  return state;
}
import type { AITask } from "@/components/smoothui/ai-task-list";
import type { AIDiffLine } from "@/components/smoothui/ai-diff";
import type { ModelCall, RunResult, RunSummary, Step } from "./api";

export type StatusMeta = { word: string; glyph: string; tone: string; text: string };

// Every state is a word plus a glyph; colour is never the only signal.
const T_RUNS = "bg-runs-soft text-runs";
const T_GAPS = "bg-gaps-soft text-gaps";
const T_BROKEN = "bg-broken-soft text-broken";
const T_CHECK = "bg-checking-soft text-checking";
const STATUS: Record<string, StatusMeta> = {
  runs: { word: "Runs", glyph: "✓", tone: T_RUNS, text: "text-runs" },
  runs_with_gaps: { word: "Runs with gaps", glyph: "◐", tone: T_GAPS, text: "text-gaps" },
  // The fix passed in the clean container but changes code and waits for the owner. Dashed outline, so
  // it can't be read as a clean pass (solid green) or as "Runs with gaps" (solid amber).
  fix_awaiting_approval: {
    word: "Fix verified · awaiting approval",
    glyph: "◆",
    tone: "border border-dashed border-gaps bg-gaps-soft text-gaps",
    text: "text-gaps",
  },
  broken: { word: "Broken", glyph: "✗", tone: T_BROKEN, text: "text-broken" },
  fail: { word: "Broken", glyph: "✗", tone: T_BROKEN, text: "text-broken" },
  // Only a record with no verifier steps at all lands here (see api/main.py).
  fixed: { word: "Fixed, unverified", glyph: "◐", tone: T_GAPS, text: "text-gaps" },
  checking: { word: "Checking", glyph: "◌", tone: T_CHECK, text: "text-checking" },
  model_limited: { word: "Model limit reached", glyph: "◌", tone: T_BROKEN, text: "text-broken" },
  unsupported: { word: "Unsupported", glyph: "◌", tone: "bg-muted text-secondary", text: "text-secondary" },
};

export const statusMeta = (status: string): StatusMeta =>
  STATUS[status] ?? { word: "Unknown", glyph: "?", tone: "bg-muted text-secondary", text: "text-secondary" };

export function fmtDur(s: number | null | undefined): string {
  if (s == null) return "—";
  if (s < 60) return `${s.toFixed(s < 10 ? 1 : 0)}s`;
  const m = Math.floor(s / 60);
  return `${m}m ${String(Math.round(s % 60)).padStart(2, "0")}s`;
}

export const shortRepo = (repo: string | null) => (repo ? repo.split("/")[1] ?? repo : "—");

export function fmtWhen(ts: number | null | undefined): string {
  if (!ts) return "";
  return new Date(ts * 1000).toLocaleString("en-GB", {
    day: "numeric", month: "short", hour: "2-digit", minute: "2-digit", timeZone: "UTC",
  }) + " UTC";
}

export const fixLabel = (kind: string | null, needsApproval: boolean) =>
  kind === "code" ? (needsApproval ? "Code · needs approval" : "Code") : kind === "config" ? "Config" : "None";

export const stepOk = (s: Step) => s.exit_code === 0;

/** Latest verified run that carries a fix; otherwise the latest run with a record. */
export function pickFeatured(runs: RunSummary[]): RunSummary | null {
  const real = runs.filter((r) => r.status !== "checking");
  return (
    real.find((r) => r.status === "runs" && r.fix_kind) ?? real.find((r) => r.status === "runs") ?? real[0] ?? null
  );
}

/** Latest run per repo (the list is newest first). */
export function latestPerRepo(runs: RunSummary[]): RunSummary[] {
  const seen = new Set<string>();
  const out: RunSummary[] = [];
  for (const r of runs) {
    const key = `${r.repo}|${r.path}`;
    if (!r.repo || r.status === "checking" || seen.has(key)) continue;
    seen.add(key);
    out.push(r);
  }
  return out;
}

export type ReplayEvent =
  | { kind: "step"; side: "agent" | "verifier"; step: Step }
  | { kind: "model"; call: ModelCall };

/** Recorded steps in order, with each model call placed where it started. */
export function buildEvents(result: RunResult): ReplayEvent[] {
  const calls = [...(result.model_calls ?? [])].sort((a, b) => (a.started ?? 0) - (b.started ?? 0));
  const events: ReplayEvent[] = [];
  let ci = 0;
  const flushCalls = (before: number | undefined) => {
    while (ci < calls.length && (before === undefined || (calls[ci].started ?? 0) < before)) {
      events.push({ kind: "model", call: calls[ci++] });
    }
  };
  for (const step of result.agent?.steps ?? []) {
    if (step.started !== undefined) flushCalls(step.started);
    events.push({ kind: "step", side: "agent", step });
  }
  flushCalls(undefined);
  for (const step of result.verifier?.steps ?? []) events.push({ kind: "step", side: "verifier", step });
  return events;
}

/** The agent's plan as a task list: each stage it ran, its repair attempts, then the verifier. */
export function buildTasks(result: RunResult): AITask[] {
  const steps = result.agent?.steps ?? [];
  const order: string[] = [];
  const last = new Map<string, Step>();
  for (const s of steps) {
    if (!last.has(s.name)) order.push(s.name);
    last.set(s.name, s);
  }
  const attempts = result.agent?.attempts ?? [];
  const tasks: AITask[] = order.map((name, i) => {
    const s = last.get(name)!;
    const runs = steps.filter((x) => x.name === name).length;
    return {
      id: `stage-${i}`,
      label: STAGE_LABEL[name] ?? name,
      status: stepOk(s) ? "done" : "failed",
      note: runs > 1 ? `${runs} runs` : fmtDur(s.duration_s),
    };
  });
  // Repairs hang off the first stage that ever failed, even if a later attempt got it through.
  const firstFailed = steps.find((s) => !stepOk(s));
  const failedStage = firstFailed ? tasks[order.indexOf(firstFailed.name)] : undefined;
  const repairs: AITask[] = attempts.map((a, i) => ({
    id: `fix-${i}`,
    label: `Repair ${i + 1}: ${a.kind ?? "fix"} in ${(a.files ?? []).join(", ") || "—"}`,
    status: a.status === "needs_approval" ? "pending" : a.result === "passed" ? "done" : "failed",
    note: a.status === "needs_approval" ? "needs approval" : undefined,
  }));
  if (repairs.length) {
    const target = failedStage ?? tasks[tasks.length - 1];
    if (target) target.children = repairs;
    else tasks.push(...repairs);
  }
  const v = result.verifier?.steps ?? [];
  tasks.push({
    id: "verify",
    label: "Rebuild in a separate clean container",
    status: v.length === 0 ? "pending" : v.every(stepOk) ? "done" : "failed",
    note: v.length === 0 ? "not reached" : fmtDur(v.reduce((a, s) => a + (s.duration_s ?? 0), 0)),
  });
  return tasks;
}

const STAGE_LABEL: Record<string, string> = {
  clone: "Fresh clone at the pinned commit",
  toolchain: "Prepare the toolchain",
  detect: "Detect the package manager",
  env: "Fill .env with dummy values",
  install: "Install dependencies",
  build: "Build",
  test: "Run tests",
  serve: "Start it and probe the port",
};

/** One AI Diff block per file in a unified patch. */
export function parsePatch(patch: string): { title: string; lines: AIDiffLine[] }[] {
  const files: { title: string; lines: AIDiffLine[] }[] = [];
  let cur: { title: string; lines: AIDiffLine[] } | null = null;
  for (const raw of patch.replace(/\n$/, "").split("\n")) {
    if (raw.startsWith("diff --git ")) {
      cur = { title: raw.replace(/^diff --git a\/(.*) b\/.*$/, "$1"), lines: [] };
      files.push(cur);
    } else if (!cur || /^(index |--- |\+\+\+ |new file|deleted file|old mode|new mode|similarity|rename )/.test(raw)) {
      continue;
    } else if (raw.startsWith("@@")) {
      cur.lines.push({ kind: "context", content: raw });
    } else if (raw.startsWith("+")) {
      cur.lines.push({ kind: "added", content: raw.slice(1) });
    } else if (raw.startsWith("-")) {
      cur.lines.push({ kind: "removed", content: raw.slice(1) });
    } else if (raw.length || cur.lines.length) {
      cur.lines.push({ kind: "context", content: raw.slice(1) });
    }
  }
  return files.filter((f) => f.lines.length);
}

/** Strip pnpm/terminal noise so output tails read cleanly. */
export const cleanLine = (l: string) => l.replace(/\u001b\[[0-9;]*m/g, "");
import { useMemo } from "react";
import { useRun, useRuns, type RunDetail, type RunSummary } from "@/lib/api";
import { latestPerRepo, pickFeatured } from "@/lib/run";

export type Problem = {
  key: string;
  title: string;
  body: string;
  /** What the run record literally says. */
  evidence: string;
  source: string;
  runId: string;
};

export type LandingData = {
  loading: boolean;
  error: string | null;
  runs: RunSummary[];
  /** The featured run's full record: the only per-run fetch the landing page makes. */
  featured: RunDetail | null;
  featuredSummary: RunSummary | null;
  /** The oldest recorded run of the featured repo: where it started out. */
  before: RunSummary | null;
  latest: RunSummary[];
  problems: Problem[];
  stats: { recorded: number; verified: number; medianVerifiedS: number | null } | null;
};

const median = (xs: number[]) => {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

const PROBLEM_COPY: Record<string, { title: string; body: string }> = {
  toolchain: {
    title: "The toolchain moved",
    body: "A package manager tightened its defaults, and a lockfile that installed last spring now refuses to install.",
  },
  runtime: {
    title: "The runtime moved",
    body: "A native module built against an older Node never learned the newer one, so the install itself fails.",
  },
  clock: {
    title: "The build never finishes",
    body: "Some projects grew past the point where a clean build completes inside a sensible time cap, and nobody noticed because nobody builds from scratch.",
  },
};

/** First run (newest first) that evidences each cause. The server did the matching. */
function findProblems(runs: RunSummary[]): Problem[] {
  return (["toolchain", "runtime", "clock"] as const).flatMap((key) => {
    for (const r of runs) {
      const p = r.problems?.find((x) => x.key === key);
      if (p) return [{ key, ...PROBLEM_COPY[key], evidence: p.evidence, source: r.repo ?? "", runId: r.id }];
    }
    return [];
  });
}

export function useLandingData(): LandingData {
  const { data: runs, loading, error } = useRuns();
  const list = useMemo(() => runs ?? [], [runs]);
  const featuredSummary = useMemo(() => pickFeatured(list), [list]);
  const { data: featured } = useRun(featuredSummary?.id ?? null);

  return useMemo(() => {
    const f = featuredSummary;
    const before = f
      ? [...list].reverse().find((r) => r.repo === f.repo && r.path === f.path && r.id !== f.id && r.status !== "checking") ?? null
      : null;
    const real = list.filter((r) => r.status !== "checking");
    // `verified` may be absent from the list; the status already says whether the clean container passed.
    const verified = real.filter((r) => r.verified ?? (r.status === "runs" || r.status === "runs_with_gaps" || r.status === "fix_awaiting_approval"));
    const fixedTimes = verified.filter((r) => r.fix_kind && r.duration_s != null).map((r) => r.duration_s as number);
    return {
      loading,
      error,
      runs: list,
      featured,
      featuredSummary: f,
      before,
      latest: latestPerRepo(list),
      problems: findProblems(real),
      stats: real.length ? { recorded: real.length, verified: verified.length, medianVerifiedS: median(fixedTimes) } : null,
    };
  }, [list, featured, featuredSummary, loading, error]);
}
