15	function ScrollToTop() {
16	  const { pathname } = useLocation();
17	  useEffect(() => window.scrollTo(0, 0), [pathname]);
18	  return null;
19	}
20	
21	/** A route change: the new page rises in with the shared entrance easing. */
22	function RouteStage({ children }: { children: ReactNode }) {
23	  const { pathname } = useLocation();
24	  return (
25	    <div key={pathname} className="route-enter">
26	      {children}
27	    </div>
28	  );
29	}
