31	function Header() {
32	  const theme = useTheme();
33	  // The one flourish: the wordmark lifts when a replayed run verifies (see lib/beat.ts).
34	  const [lifted, setLifted] = useState(false);
35	  useEffect(() => {
36	    let id = 0;
37	    const on = () => {
38	      setLifted(true);
39	      window.clearTimeout(id);
40	      id = window.setTimeout(() => setLifted(false), 560);
41	    };
42	    window.addEventListener(LIFT_EVENT, on);
