50	  return (
51	    <header className="sticky top-0 z-30 border-b border-border bg-background/85 backdrop-blur">
52	      <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6">
53	        <Link to="/" aria-label="Resurgo, home" className="flex items-center">
54	          {/* The brand's lifted-r wordmark; the file is chosen for the background it sits on. */}
55	          <img
56	            src={theme === "dark" ? "/brand/logo-wordmark-dark.svg" : "/brand/logo-wordmark-light.svg"}
57	            alt="resurgo"
58	            width={120}
59	            height={28}
60	            className={`h-7 w-auto ${lifted ? "lift" : ""}`}
61	          />
62	        </Link>
63	        <nav aria-label="Main" className="flex items-center gap-4 sm:gap-6">
64	          <NavLink to="/runs" className={link}>Runs</NavLink>
65	          <a
66	            href={INSTALL_URL}
67	            className="press inline-flex min-h-9 items-center gap-2 rounded-lg border border-accent-strong bg-accent-strong px-3 text-sm font-semibold text-on-accent hover:opacity-90"
68	          >
69	            <Logo name="github" size="1.25em" decorative />
70	            <span>Install<span className="hidden sm:inline">{" on GitHub"}</span></span>
71	          </a>
72	          <ThemeToggle />
73	        </nav>
74	      </div>
75	    </header>
76	  );
77	}
78	
79	function Footer() {
80	  return (
81	    <footer className="border-t border-border">
82	      <div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-10 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between sm:px-6">
83	        <p>Resurgo, pronounced reh-SUR-go: Latin for &ldquo;I rise again&rdquo;. Built for neatHack, 10 to 12 October 2026.</p>
84	        <p className="flex flex-wrap items-center gap-x-5 gap-y-1">
85	          <a href="/index.md" className="font-semibold text-foreground underline underline-offset-4">Agent view</a>
86	          <span>Not affiliated with the tools or repositories named on this site.</span>
87	        </p>
88	      </div>
89	    </footer>
90	  );
91	}
92	
93	export default function App() {
94	  return (
